from pathlib import Path
import time
import math

import numpy as np
import pandas as pd
import soundfile as sf
import torch
import torch.nn.functional as F

from scipy.signal import resample_poly
from pystoi import stoi
from transformers import AutoFeatureExtractor, AutoModel


# ============================================================
# ELEC5305 FINAL PROJECT
#
# Does Wiener Filtering Help Modern Speech Foundation Models?
# A Layer-Wise Analysis
#
# This script:
# 1. Reads the 32 controlled experiments generated by MATLAB.
# 2. Calculates STOI for noisy and Wiener-enhanced speech.
# 3. Extracts frozen representations from:
#       - WavLM Base+
#       - HuBERT Base
# 4. Analyses four representative network layers.
# 5. Calculates:
#       cosine(clean, noisy)
#       cosine(clean, Wiener)
#       recovery score
# 6. Saves experiment-level and summary CSV files.
# ============================================================


# ============================================================
# 1. Project configuration
# ============================================================

PROJECT_DIR = Path(__file__).resolve().parents[1]

MIXTURE_DIR = PROJECT_DIR / "data" / "mixtures"

METADATA_FILE = MIXTURE_DIR / "mixture_metadata.csv"

RESULTS_DIR = PROJECT_DIR / "results" / "final"

RESULTS_DIR.mkdir(parents=True, exist_ok=True)

TARGET_SR = 16000

# MATLAB generator adds one second of noise-only calibration.
# We remove it before STOI and foundation-model analysis.
CALIBRATION_SECONDS = 1.0

DEVICE = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

MODELS = {
    "WavLM_BasePlus": "microsoft/wavlm-base-plus",
    "HuBERT_Base": "facebook/hubert-base-ls960",
}


# ============================================================
# 2. Audio utilities
# ============================================================

def load_audio(path: Path):
    """
    Load mono audio and resample to 16 kHz if required.
    """

    audio, sr = sf.read(path, dtype="float32")

    if audio.ndim > 1:
        audio = np.mean(audio, axis=1)

    audio = np.asarray(audio, dtype=np.float32)

    if sr != TARGET_SR:
        gcd_value = math.gcd(sr, TARGET_SR)

        up = TARGET_SR // gcd_value
        down = sr // gcd_value

        audio = resample_poly(
            audio,
            up,
            down
        ).astype(np.float32)

        sr = TARGET_SR

    return audio, sr


def remove_calibration(audio):
    """
    Remove the one-second initial noise-only calibration region.
    """

    trim_samples = int(
        CALIBRATION_SECONDS * TARGET_SR
    )

    if len(audio) <= trim_samples:
        raise ValueError(
            "Audio is shorter than calibration region."
        )

    return audio[trim_samples:]


def align_signals(clean, noisy, wiener):
    """
    Ensure all three signals contain exactly the same number
    of samples after removing the calibration region.
    """

    min_length = min(
        len(clean),
        len(noisy),
        len(wiener)
    )

    clean = clean[:min_length]
    noisy = noisy[:min_length]
    wiener = wiener[:min_length]

    return clean, noisy, wiener


# ============================================================
# 3. STOI evaluation
# ============================================================

def calculate_stoi(clean, test):
    """
    Calculate Short-Time Objective Intelligibility.
    """

    score = stoi(
        clean,
        test,
        TARGET_SR,
        extended=False
    )

    return float(score)


# ============================================================
# 4. Foundation-model representation utilities
# ============================================================

def choose_layers(hidden_states):
    """
    Select four representative transformer depths:
        early
        lower-middle
        upper-middle
        final

    hidden_states[0] is the feature-projection representation,
    so transformer layers begin at index 1.
    """

    final_layer = len(hidden_states) - 1

    selected = [
        1,
        max(1, round(final_layer / 3)),
        max(1, round(2 * final_layer / 3)),
        final_layer
    ]

    # Remove duplicates while preserving order.
    selected = list(dict.fromkeys(selected))

    return selected


def layer_labels(layer_indices):
    """
    Human-readable labels for the selected layers.
    """

    names = [
        "early",
        "lower_middle",
        "upper_middle",
        "final"
    ]

    return {
        layer: names[i]
        for i, layer in enumerate(layer_indices)
    }


def average_frame_cosine(reference, test):
    """
    Calculate frame-wise cosine similarity and then average
    across time.

    Input shape:
        [frames, hidden_dimension]
    """

    min_frames = min(
        reference.shape[0],
        test.shape[0]
    )

    reference = reference[:min_frames]
    test = test[:min_frames]

    similarity = F.cosine_similarity(
        reference,
        test,
        dim=-1,
        eps=1e-8
    )

    return float(
        similarity.mean().item()
    )


# ============================================================
# 5. Model evaluation
# ============================================================

def evaluate_model(
    model_name,
    model_id,
    metadata,
    signal_metric_lookup
):
    """
    Evaluate one frozen foundation model across all 32
    experiments.
    """

    print()
    print("=" * 70)
    print(f"Loading model: {model_name}")
    print(f"Hugging Face ID: {model_id}")
    print("=" * 70)

    feature_extractor = (
        AutoFeatureExtractor.from_pretrained(
            model_id
        )
    )

    model = AutoModel.from_pretrained(
        model_id
    )

    model.to(DEVICE)
    model.eval()

    print(f"Device: {DEVICE}")

    model_results = []

    selected_layers = None
    selected_layer_labels = None

    total_experiments = len(metadata)

    model_start_time = time.time()

    for index, row in metadata.iterrows():

        experiment_id = row["experiment_id"]

        print()
        print(
            f"[{index + 1:02d}/{total_experiments:02d}] "
            f"{model_name} | {experiment_id} | "
            f"{row['noise_type']} | "
            f"{row['target_snr_db']:+.0f} dB"
        )

        clean_path = (
            PROJECT_DIR / row["clean_path"]
        )

        noisy_path = (
            PROJECT_DIR / row["noisy_path"]
        )

        wiener_path = (
            PROJECT_DIR / row["wiener_path"]
        )

        clean, _ = load_audio(clean_path)
        noisy, _ = load_audio(noisy_path)
        wiener, _ = load_audio(wiener_path)

        # Remove one-second noise-estimation region.
        clean = remove_calibration(clean)
        noisy = remove_calibration(noisy)
        wiener = remove_calibration(wiener)

        clean, noisy, wiener = align_signals(
            clean,
            noisy,
            wiener
        )

        # Process clean / noisy / Wiener as one batch.
        inputs = feature_extractor(
            [
                clean,
                noisy,
                wiener
            ],
            sampling_rate=TARGET_SR,
            return_tensors="pt",
            padding=True,
            return_attention_mask=True
        )

        model_inputs = {
            key: value.to(DEVICE)
            for key, value in inputs.items()
        }

        experiment_start = time.time()

        with torch.no_grad():

            outputs = model(
                **model_inputs,
                output_hidden_states=True,
                return_dict=True
            )

        hidden_states = outputs.hidden_states

        # Select representative layers once.
        if selected_layers is None:

            selected_layers = choose_layers(
                hidden_states
            )

            selected_layer_labels = (
                layer_labels(
                    selected_layers
                )
            )

            print(
                f"Selected transformer layers: "
                f"{selected_layers}"
            )

        for layer_index in selected_layers:

            layer_output = (
                hidden_states[layer_index]
                .detach()
                .cpu()
            )

            clean_rep = layer_output[0]
            noisy_rep = layer_output[1]
            wiener_rep = layer_output[2]

            noisy_similarity = (
                average_frame_cosine(
                    clean_rep,
                    noisy_rep
                )
            )

            wiener_similarity = (
                average_frame_cosine(
                    clean_rep,
                    wiener_rep
                )
            )

            recovery_score = (
                wiener_similarity
                - noisy_similarity
            )

            signal_metrics = (
                signal_metric_lookup[
                    experiment_id
                ]
            )

            result_row = {
                "experiment_id":
                    experiment_id,

                "speaker_id":
                    row["speaker_id"],

                "utterance_id":
                    row["utterance_id"],

                "noise_type":
                    row["noise_type"],

                "target_snr_db":
                    row["target_snr_db"],

                "measured_input_snr_db":
                    row[
                        "measured_input_snr_db"
                    ],

                "output_snr_db":
                    row["output_snr_db"],

                "snr_improvement_db":
                    row[
                        "snr_improvement_db"
                    ],

                "stoi_noisy":
                    signal_metrics[
                        "stoi_noisy"
                    ],

                "stoi_wiener":
                    signal_metrics[
                        "stoi_wiener"
                    ],

                "stoi_improvement":
                    signal_metrics[
                        "stoi_improvement"
                    ],

                "model":
                    model_name,

                "model_id":
                    model_id,

                "layer":
                    layer_index,

                "layer_position":
                    selected_layer_labels[
                        layer_index
                    ],

                "clean_noisy_similarity":
                    noisy_similarity,

                "clean_wiener_similarity":
                    wiener_similarity,

                "recovery_score":
                    recovery_score,
            }

            model_results.append(
                result_row
            )

            print(
                f"  Layer {layer_index:02d} "
                f"({selected_layer_labels[layer_index]}): "
                f"noisy={noisy_similarity:.4f}, "
                f"Wiener={wiener_similarity:.4f}, "
                f"recovery={recovery_score:+.4f}"
            )

        elapsed = time.time() - experiment_start

        print(
            f"  Forward-pass time: "
            f"{elapsed:.2f} s"
        )

        # Free tensors before next experiment.
        del outputs
        del hidden_states
        del model_inputs
        del inputs

        if torch.cuda.is_available():
            torch.cuda.empty_cache()

    total_time = time.time() - model_start_time

    print()
    print(
        f"{model_name} completed in "
        f"{total_time / 60:.2f} minutes."
    )

    # Remove model before loading the second model.
    del model
    del feature_extractor

    if torch.cuda.is_available():
        torch.cuda.empty_cache()

    return model_results


# ============================================================
# 6. Main experiment
# ============================================================

def main():

    print()
    print("=" * 70)
    print("ELEC5305 FINAL FOUNDATION-MODEL EVALUATION")
    print("=" * 70)

    print(f"Project directory: {PROJECT_DIR}")
    print(f"Device: {DEVICE}")

    if not METADATA_FILE.exists():
        raise FileNotFoundError(
            f"Metadata not found: "
            f"{METADATA_FILE}"
        )

    metadata = pd.read_csv(
        METADATA_FILE
    )

    print(
        f"Loaded {len(metadata)} experiments."
    )

    if len(metadata) != 32:

        print(
            "WARNING: Expected 32 experiments, "
            f"but found {len(metadata)}."
        )

    # ========================================================
    # 7. Signal-level STOI evaluation
    # ========================================================

    print()
    print("=" * 70)
    print("STEP 1: STOI EVALUATION")
    print("=" * 70)

    signal_rows = []

    signal_metric_lookup = {}

    for index, row in metadata.iterrows():

        experiment_id = row["experiment_id"]

        clean_path = (
            PROJECT_DIR / row["clean_path"]
        )

        noisy_path = (
            PROJECT_DIR / row["noisy_path"]
        )

        wiener_path = (
            PROJECT_DIR / row["wiener_path"]
        )

        clean, _ = load_audio(clean_path)
        noisy, _ = load_audio(noisy_path)
        wiener, _ = load_audio(wiener_path)

        clean = remove_calibration(clean)
        noisy = remove_calibration(noisy)
        wiener = remove_calibration(wiener)

        clean, noisy, wiener = align_signals(
            clean,
            noisy,
            wiener
        )

        stoi_noisy = calculate_stoi(
            clean,
            noisy
        )

        stoi_wiener = calculate_stoi(
            clean,
            wiener
        )

        stoi_improvement = (
            stoi_wiener
            - stoi_noisy
        )

        signal_row = {
            "experiment_id":
                experiment_id,

            "speaker_id":
                row["speaker_id"],

            "utterance_id":
                row["utterance_id"],

            "noise_type":
                row["noise_type"],

            "target_snr_db":
                row["target_snr_db"],

            "measured_input_snr_db":
                row[
                    "measured_input_snr_db"
                ],

            "output_snr_db":
                row["output_snr_db"],

            "snr_improvement_db":
                row[
                    "snr_improvement_db"
                ],

            "stoi_noisy":
                stoi_noisy,

            "stoi_wiener":
                stoi_wiener,

            "stoi_improvement":
                stoi_improvement,
        }

        signal_rows.append(
            signal_row
        )

        signal_metric_lookup[
            experiment_id
        ] = signal_row

        print(
            f"[{index + 1:02d}/"
            f"{len(metadata):02d}] "
            f"{experiment_id}: "
            f"STOI noisy={stoi_noisy:.4f}, "
            f"Wiener={stoi_wiener:.4f}, "
            f"change={stoi_improvement:+.4f}"
        )

    signal_df = pd.DataFrame(
        signal_rows
    )

    signal_file = (
        RESULTS_DIR
        / "signal_metrics.csv"
    )

    signal_df.to_csv(
        signal_file,
        index=False
    )

    # ========================================================
    # 8. STOI summary
    # ========================================================

    signal_summary = (
        signal_df
        .groupby(
            [
                "noise_type",
                "target_snr_db"
            ]
        )
        .agg(
            count=(
                "experiment_id",
                "count"
            ),

            mean_snr_improvement_db=(
                "snr_improvement_db",
                "mean"
            ),

            std_snr_improvement_db=(
                "snr_improvement_db",
                "std"
            ),

            mean_stoi_noisy=(
                "stoi_noisy",
                "mean"
            ),

            mean_stoi_wiener=(
                "stoi_wiener",
                "mean"
            ),

            mean_stoi_improvement=(
                "stoi_improvement",
                "mean"
            ),

            std_stoi_improvement=(
                "stoi_improvement",
                "std"
            )
        )
        .reset_index()
    )

    signal_summary.to_csv(
        RESULTS_DIR
        / "signal_metrics_summary.csv",
        index=False
    )

    print()
    print("STOI SUMMARY")
    print(signal_summary.to_string(index=False))

    # ========================================================
    # 9. Foundation-model evaluation
    # ========================================================

    print()
    print("=" * 70)
    print("STEP 2: FOUNDATION-MODEL REPRESENTATIONS")
    print("=" * 70)

    all_representation_results = []

    for model_name, model_id in MODELS.items():

        model_results = evaluate_model(
            model_name,
            model_id,
            metadata,
            signal_metric_lookup
        )

        all_representation_results.extend(
            model_results
        )

    representation_df = pd.DataFrame(
        all_representation_results
    )

    representation_file = (
        RESULTS_DIR
        / "representation_results.csv"
    )

    representation_df.to_csv(
        representation_file,
        index=False
    )

    # ========================================================
    # 10. Utterance-level / condition summary
    # ========================================================
    #
    # Each experiment remains the independent unit.
    # We calculate mean and standard deviation across
    # utterances rather than treating individual frames
    # as independent experiments.
    # ========================================================

    representation_summary = (
        representation_df
        .groupby(
            [
                "model",
                "layer",
                "layer_position",
                "noise_type",
                "target_snr_db"
            ]
        )
        .agg(
            count=(
                "experiment_id",
                "count"
            ),

            mean_clean_noisy_similarity=(
                "clean_noisy_similarity",
                "mean"
            ),

            std_clean_noisy_similarity=(
                "clean_noisy_similarity",
                "std"
            ),

            mean_clean_wiener_similarity=(
                "clean_wiener_similarity",
                "mean"
            ),

            std_clean_wiener_similarity=(
                "clean_wiener_similarity",
                "std"
            ),

            mean_recovery_score=(
                "recovery_score",
                "mean"
            ),

            std_recovery_score=(
                "recovery_score",
                "std"
            )
        )
        .reset_index()
    )

    representation_summary.to_csv(
        RESULTS_DIR
        / "representation_summary.csv",
        index=False
    )

    # ========================================================
    # 11. Model-level overall summary
    # ========================================================

    overall_summary = (
        representation_df
        .groupby(
            [
                "model",
                "layer",
                "layer_position"
            ]
        )
        .agg(
            mean_recovery_score=(
                "recovery_score",
                "mean"
            ),

            std_recovery_score=(
                "recovery_score",
                "std"
            ),

            positive_recovery_fraction=(
                "recovery_score",
                lambda x: float(
                    np.mean(
                        np.asarray(x) > 0
                    )
                )
            )
        )
        .reset_index()
    )

    overall_summary.to_csv(
        RESULTS_DIR
        / "model_layer_overall_summary.csv",
        index=False
    )

    # ========================================================
    # 12. Final console summary
    # ========================================================

    print()
    print("=" * 70)
    print("FINAL REPRESENTATION SUMMARY")
    print("=" * 70)

    print(
        overall_summary.to_string(
            index=False
        )
    )

    print()
    print("Generated files:")
    print(
        "  results/final/"
        "signal_metrics.csv"
    )
    print(
        "  results/final/"
        "signal_metrics_summary.csv"
    )
    print(
        "  results/final/"
        "representation_results.csv"
    )
    print(
        "  results/final/"
        "representation_summary.csv"
    )
    print(
        "  results/final/"
        "model_layer_overall_summary.csv"
    )

    print()
    print(
        "Interpretation of recovery score:"
    )
    print(
        "  > 0 : Wiener moved representation "
        "toward clean speech"
    )
    print(
        "  ~ 0 : Wiener added little "
        "representation benefit"
    )
    print(
        "  < 0 : Wiener moved representation "
        "away from clean speech"
    )

    print()
    print(
        "FOUNDATION-MODEL EVALUATION "
        "COMPLETED SUCCESSFULLY."
    )
    print("=" * 70)


if __name__ == "__main__":
    main()